UPDATE  stra_his_file
SET  zip_status=1,
update_time=now(),
md5=#{md5}
where
api_code=#{apiCode}
AND
create_time>date_add(curdate(), interval -1 day)

	AND zipFile_name=#{fileName}


	AND batch_number=#{batchNumber}


	AND data_type=2

UPDATE stra_his_file
SET status=2,
update_time=now()
where api_code = #{apiCode}
AND zipFile_name = #{fileName}

    AND batch_number = #{batchNumber}

UPDATE stra_his_file
SET status =0,
zipFile_name=#{zipFileName},
